//! The traits a user implements (`ComponentSubscription` via the derive,
//! `Component` by hand) and the type-level dependency list the derive builds.

use std::marker::PhantomData;

use crate::node::Vertex;

use crate::select::SelectChain;

/// What a component subscribes to. Generated by
/// `#[derive(ComponentSubscription)]` from `#[subscribe(name: Type, ...)]`.
pub trait ComponentSubscription: 'static {
    /// The subscriptions as a type-level tree of tuples (see [`DepList`]),
    /// walked by the plan. Listing order is the order of `#[subscribe(...)]`.
    type Deps: DepList;
    /// A struct with one named reference per subscription: what `update` gets.
    type Input<'a>;
    /// A struct with one named entry per subscription: what `new` gets. An
    /// entry is `&Output` for a component and `()` for the root.
    type Init<'a>;
    /// Name the runtime's nested tuple of references.
    fn input<'a>(raw: <Self::Deps as DepList>::Inputs<'a>) -> Self::Input<'a>;
    /// Name the construction pass's nested tuple.
    fn init<'a>(raw: <Self::Deps as DepList>::Inits<'a>) -> Self::Init<'a>;
    /// For a `#[listener]`: put the requests collected by the first pass into
    /// `init.requests`. Nothing for other components.
    #[doc(hidden)]
    fn __fill_requests(_: &mut Self::Init<'_>, _: &mut crate::build::ConstructPass) {}
}

/// A stateful node of the dataflow graph.
///
/// # Execution order
///
/// The order in which `update` is called in a step is part of the contract: a
/// depth-first post-order that follows subscription listing order. For a
/// component `C` subscribing to `[D1, .., Dn]` (in `#[subscribe]` order), the
/// runs during `C`'s walk come in `n` blocks followed by `C` itself. Block `i`
/// is `Di` plus everything upstream of `Di` that has not already run in this
/// step, itself in this same order. The blocks come in listing order, so a
/// later-listed dependency that is upstream of an earlier one runs inside the
/// earlier block. A component runs at most once per step, after everything it
/// subscribes to. (A component runs only when one of its edges fired; see the README.)
/// `Pipeline::order` reports the *construction* order, which is the same order.
///
/// # Stored outputs
///
/// The output of a component is stored in the pipeline: it is what its
/// subscribers read, in this step if it ran, and in later steps otherwise. The
/// construction call `new` also produces an output, so there is a value to
/// read before the component has run for the first time.
pub trait Component: ComponentSubscription + Sized {
    /// Owned configuration passed to `new`. Components without an entry in
    /// [`Configs`](crate::Configs) get `Default::default()`.
    type Config: Default + 'static;
    /// What `update` produces; subscribers receive `&Output`.
    type Output: 'static;

    /// Called once, when the pipeline is built, in execution order. `init`
    /// has the outputs the subscriptions had when they were constructed
    /// (earlier in the order). Returns the component and its first output.
    fn new(config: Self::Config, init: Self::Init<'_>) -> (Self, Self::Output);

    /// Called when this component runs in a step, after everything it
    /// subscribes to. The returned output replaces the stored one.
    fn update(&mut self, input: Self::Input<'_>) -> Self::Output;
}

/// A component whose subscribers read a *view* computed from its state, not a stored value.
///
/// Select it with `#[handle]` next to `#[derive(ComponentSubscription)]`. The pipeline stores the
/// [`Handle`](Self::Handle) `update` returns (a slot index, a key, `()`), and a subscriber's field
/// is exactly [`View<'a>`](Self::View): `view(&self, &handle)`, evaluated by the framework
/// each time a subscriber runs (or is constructed). Nothing is cached, so `view` should be
/// cheap (an index, a reference into the state). The subscriber's field is the view as it is,
/// owned or a reference: no `&` is added. A subscriber of a handle component reads the parent's
/// state and handle as of this moment, also in steps where the parent did not run.
///
/// `Handle` needs no `Copy`: the framework only stores it and lends it to `view`.
///
/// Not supported yet: selectors on a handle component (`Some(X(v)): Parent`), `#[listener]`.
pub trait HandleComponent: ComponentSubscription + Sized {
    /// Owned configuration passed to `new`, as for [`Component::Config`].
    type Config: Default + 'static;
    /// What the pipeline stores between steps.
    type Handle: 'static;
    /// What subscribers read.
    type View<'a>
    where
        Self: 'a;
    /// As [`Component::new`], but the first output is a handle.
    fn new(config: Self::Config, init: Self::Init<'_>) -> (Self, Self::Handle);
    /// As [`Component::update`]; the returned handle replaces the stored one.
    fn update(&mut self, input: Self::Input<'_>) -> Self::Handle;
    /// The view of the state and the stored handle that subscribers read.
    fn view<'a>(&'a self, handle: &'a Self::Handle) -> Self::View<'a>;
}

/// One entry of a subscription tree: the node `N` listed at position `I`
/// of its subscriber's list of unique subscriptions (listing order, after the
/// derive merges entries spelled alike), read through the selector chain `C`
/// (`()` for a plain subscription). The position tells apart two entries
/// that name the same type (`a: X, b: Y` with `type Y = X;`, or `a: X, b: X =>
/// Some`), so the plan can say which of them is the one that reached `X` first
/// ([`Plan::first_pos_of`](crate::plan::Plan)). A marker: never constructed.
#[doc(hidden)]
pub struct Sub<N, C, const I: usize, X>(PhantomData<(N, C, X)>);

/// A node of the subscription tree: the type the derive builds for
/// [`ComponentSubscription::Deps`]. User code never writes one.
///
/// Rust has no variadic generics, so every recursive operation in this crate
/// (plan, gathering inputs, cycle check) is a handful of impls, one per node
/// *shape*:
///
/// In the shapes below an entry `A` stands for [`Sub<A, i>`](Sub), `i` being
/// its position in the listing.
///
/// * a leaf, a plain tuple of 0 to `ARITY - 1` (15) nodes: `()` (no
///   subscriptions), `(A,)`, `(A, B)`, and so on;
/// * an inner node, exactly a tuple of `ARITY` (16) child nodes and no
///   entries of its own (unused children are the empty leaf `()`), used for
///   more than 15 subscriptions. A tuple of 16 is therefore always an inner
///   node and a shorter one always a leaf.
///
/// Listing order is the leaves left to right. The derive keeps the tree as
/// shallow as possible and fills it from the left: with `d` the least depth
/// whose capacity `15 * 16^d` holds the subscriptions, the 16 children get
/// `15 * 16^(d-1)` each, in order, until nothing is left (depth grows with
/// log16 of the number of subscriptions).
///
/// `ARITY` is defined in `dataflow-macros`, the only place it is written:
/// the impls for each shape below are generated from it by the callback macros
/// `leaf_shapes!` and `inner_shape!`.
pub trait DepList: 'static {
    /// The nested tuple of references `update` is handed, before the derive
    /// names its fields. It has the shape of the node.
    type Inputs<'a>;
    /// The nested tuple `new` is handed.
    type Inits<'a>;
    /// The number of entries in the tree.
    const LEN: usize;
}

macro_rules! dep_list_leaf {
    ([$($E:ident $C:ident $I:ident $X:ident)*]) => {
        impl<$($E: Vertex, $C: SelectChain<$E::Stored>, const $I: usize, $X: 'static,)*> DepList for ($(Sub<$E, $C, $I, $X>,)*) {
            type Inputs<'a> = ($(<$C as SelectChain<$E::Stored>>::Read<'a, $E>,)*);
            type Inits<'a> = ($(<$C as SelectChain<$E::Stored>>::Init<'a, $E>,)*);
            const LEN: usize = [$(stringify!($E),)* ""].len() - 1;
        }
    };
}
dataflow_macros::leaf_shapes!(dep_list_leaf);

macro_rules! dep_list_inner {
    ([$($K:ident)*]) => {
        impl<$($K: DepList,)*> DepList for ($($K,)*) {
            type Inputs<'a> = ($($K::Inputs<'a>,)*);
            type Inits<'a> = ($($K::Inits<'a>,)*);
            const LEN: usize = 0 $(+ $K::LEN)*;
        }
    };
}
dataflow_macros::inner_shape!(dep_list_inner);
